const body = $input.first().json.body;
const required = ['project_id', 'event_type', 'description'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const eventTypes = ['milestone', 'issue', 'payment', 'decision', 'delay', 'inspection', 'quote_received', 'work_completed', 'material_ordered', 'note'];
const eventType = eventTypes.includes(body.event_type) ? body.event_type : 'note';

const amount = body.amount ? parseFloat(body.amount) : null;

return [{
  json: {
    valid: true,
    mode: 'log',
    eventId: `EV-${Date.now()}`,
    projectId: body.project_id.trim(),
    eventType,
    description: body.description.trim().slice(0, 800),
    amount,
    vendor: body.vendor || '',
    phase: body.phase || '',
    isBlocker: body.is_blocker === true || body.is_blocker === 'true',
    photoUrls: Array.isArray(body.photo_urls) ? body.photo_urls.slice(0, 3) : [],
    eventDate: body.event_date || new Date().toISOString().split('T')[0],
    loggedAt: new Date().toISOString()
  }
}];

const body = $input.first().json.body;
const required = ['project_id', 'project_name', 'scope_description', 'contractor_trade'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}
return [{
  json: {
    valid: true,
    mode: 'brief',
    projectId: body.project_id.trim(),
    projectName: body.project_name.trim(),
    scopeDescription: body.scope_description.trim().slice(0, 2000),
    contractorTrade: body.contractor_trade.trim(),
    contractorName: body.contractor_name || '',
    houseDetails: (body.house_details || '').slice(0, 600),
    budget: body.budget || '',
    timeline: body.timeline || '',
    specificRequirements: (body.specific_requirements || '').slice(0, 600),
    materialsPreference: body.materials_preference || '',
    accessDetails: (body.access_details || '').slice(0, 300),
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

const allEvents = $('Load Project Events').all().map(r => r.json);
const current = $('Validate Event').first().json;

const projectEvents = allEvents
  .filter(e => e.project_id === current.projectId && e.event_id !== current.eventId)
  .sort((a, b) => new Date(b.event_date) - new Date(a.event_date));

const totalSpent = projectEvents
  .filter(e => e.amount && parseFloat(e.amount) > 0)
  .reduce((s, e) => s + parseFloat(e.amount), 0);

const blockers = projectEvents.filter(e => e.is_blocker === 'TRUE' || e.is_blocker === true);
const recentEvents = projectEvents.slice(0, 8);

return [{
  json: {
    current,
    projectId: current.projectId,
    totalSpent: parseFloat(totalSpent.toFixed(2)),
    activeBlockers: blockers.filter(b => b.resolved !== 'TRUE').length,
    totalEvents: projectEvents.length,
    recentEvents,
    currency: $env.RENO_CURRENCY || 'USD'
  }
}];

const d = $input.first().json;
const cur = d.currency;
const ev = d.current;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const eventTypeConfig = {
  milestone:        { color: '#16a34a', bg: '#f0fdf4', icon: '🏁' },
  issue:            { color: '#dc2626', bg: '#fef2f2', icon: '⚠️' },
  payment:          { color: '#2563eb', bg: '#eff6ff', icon: '💳' },
  decision:         { color: '#7c3aed', bg: '#f5f3ff', icon: '✅' },
  delay:            { color: '#d97706', bg: '#fffbeb', icon: '⏱' },
  inspection:       { color: '#0369a1', bg: '#e0f2fe', icon: '🔍' },
  quote_received:   { color: '#0891b2', bg: '#ecfeff', icon: '📋' },
  work_completed:   { color: '#16a34a', bg: '#f0fdf4', icon: '✔️' },
  material_ordered: { color: '#9333ea', bg: '#faf5ff', icon: '📦' },
  note:             { color: '#6b7280', bg: '#f9fafb', icon: '📝' }
};
const ec = eventTypeConfig[ev.eventType] || eventTypeConfig.note;

const recentRows = d.recentEvents.map(e => {
  const cfg = eventTypeConfig[e.event_type] || eventTypeConfig.note;
  return `<div style="display:flex;gap:12px;padding:8px 0;border-bottom:1px solid #f3f4f6;align-items:flex-start">
    <span style="font-size:14px;margin-top:1px">${cfg.icon}</span>
    <div style="flex:1">
      <div style="font-size:13px;color:#374151;line-height:1.5">${esc(e.description)}</div>
      <div style="font-size:11px;color:#9ca3af;margin-top:2px">${esc(e.event_date)}${e.vendor ? ' · ' + esc(e.vendor) : ''}${e.amount ? ' · ' + cur + parseFloat(e.amount).toFixed(2) : ''}</div>
    </div>
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:560px;margin:0 auto">
  <div style="background:#1c1917;color:#fff;padding:18px 24px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#78716c;margin-bottom:4px">Project Log · ${esc(ev.projectId)}</div>
    <div style="font-size:18px;font-weight:700">${ec.icon} ${esc(ev.eventType.replace(/_/g,' '))}</div>
    <div style="font-size:12px;color:#78716c;margin-top:3px">${esc(ev.eventDate)}${ev.isBlocker ? ' · <span style="color:#f87171">⚡ BLOCKER</span>' : ''}</div>
  </div>
  <div style="background:${ec.bg};border:1px solid ${ec.color}33;padding:16px 24px">
    <p style="font-size:15px;line-height:1.7;color:#1c1917;margin:0">${esc(ev.description)}</p>
    ${ev.amount ? `<div style="margin-top:10px;font-size:14px;font-weight:700;color:${ec.color}">${cur} ${parseFloat(ev.amount).toFixed(2)}${ev.vendor ? ' · ' + esc(ev.vendor) : ''}</div>` : ''}
  </div>
  <div style="background:#fff;padding:16px 24px;border:1px solid #e5e7eb;border-top:none">
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;font-size:13px;text-align:center">
      <div><div style="color:#9ca3af;font-size:11px;text-transform:uppercase">Total spent</div><strong>${cur} ${d.totalSpent.toFixed(2)}</strong></div>
      <div><div style="color:#9ca3af;font-size:11px;text-transform:uppercase">Events logged</div><strong>${d.totalEvents + 1}</strong></div>
      <div><div style="color:${d.activeBlockers > 0 ? '#dc2626' : '#9ca3af'};font-size:11px;text-transform:uppercase">Blockers</div><strong style="color:${d.activeBlockers > 0 ? '#dc2626' : '#111'}">${d.activeBlockers}</strong></div>
    </div>
  </div>
  ${recentRows ? `<div style="background:#fff;padding:16px 24px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;letter-spacing:0.4px;margin-bottom:8px">Recent activity</div>
    ${recentRows}
  </div>` : ''}
  <div style="background:#1c1917;color:#57534e;font-size:11px;padding:10px 24px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Home Reno Tracker · ${esc(ev.projectId)}
  </div>
</div>
</body></html>`;

return [{ json: { html, projectId: ev.projectId, isBlocker: ev.isBlocker, eventType: ev.eventType } }];

