Write a contractor briefing document.

Project: {{ $json.projectName }} (ID: {{ $json.projectId }})
Trade: {{ $json.contractorTrade }}{{ $json.contractorName ? ' — Contractor: ' + $json.contractorName : '' }}
Budget: {{ $json.budget || 'not specified' }}
Timeline: {{ $json.timeline || 'not specified' }}

Scope:
{{ $json.scopeDescription }}

House details:
{{ $json.houseDetails || 'not provided' }}

Specific requirements:
{{ $json.specificRequirements || 'none' }}

Materials preference:
{{ $json.materialsPreference || 'not specified' }}

Access details:
{{ $json.accessDetails || 'not specified' }}

Generate this JSON:
{
  "brief_title": "short descriptive title for this brief",
  "project_summary": "2-3 sentences summarizing the job — what needs to be done, what the end state looks like, and any key constraints",
  "scope_of_work": [
    {
      "item": "specific task or deliverable",
      "details": "what exactly is needed, any specs or preferences",
      "priority": "must_have | nice_to_have"
    }
  ],
  "out_of_scope": ["things that are explicitly NOT part of this job — prevents scope creep"],
  "site_conditions": "what the contractor will find when they arrive — access, existing conditions, any quirks",
  "materials": {
    "supplied_by_homeowner": ["materials the homeowner is providing"],
    "supplied_by_contractor": ["materials contractor should source and price"],
    "specifications": "any specific brands, grades, or standards required"
  },
  "access_and_logistics": "practical details about how to access the property, parking, working hours, where to store materials",
  "success_criteria": ["how the homeowner will know the job is done correctly — specific, measurable where possible"],
  "questions_to_answer_in_quote": ["specific questions the homeowner wants addressed in the quote — things that will affect their decision"],
  "timeline_expectations": "what the homeowner expects in terms of start date, duration, and any hard deadlines",
  "communication_preferences": "how the homeowner wants to be updated during the job",
  "warnings_for_contractor": ["anything the contractor should know to avoid surprises — old pipes, asbestos era house, quirky existing work, pet on premises, etc."]
}

