const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let brief;
try {
  brief = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Brief Request').first().json;
brief._meta = {
  projectName: input.projectName,
  contractorTrade: input.contractorTrade,
  contractorName: input.contractorName,
  budget: input.budget,
  replyEmail: input.replyEmail
};
return [{ json: brief }];
